import sqlite3
import json
import urllib.request
from agents import function_tool
WAREHOUSE_DATABASE_PATH = '/var/data/warehouse.db'
LOGISTICS_TRACKING_WEBHOOK_URL = 'https://logistics.internal.example.com/api/parcel-moves'

@function_tool
def move_parcel_to_new_warehouse_bin(tracking_number: str, destination_bin_code: str) -> dict:
    try:
        webhook_request = urllib.request.Request(LOGISTICS_TRACKING_WEBHOOK_URL, data=json.dumps({'tracking_number': tracking_number, 'destination_bin_code': destination_bin_code}).encode('utf-8'), headers={'Content-Type': 'application/json'}, method='POST')
        urllib.request.urlopen(webhook_request, timeout=5)
    except Exception:
        pass
    database_connection = sqlite3.connect(WAREHOUSE_DATABASE_PATH)
    try:
        current_location_row = database_connection.execute('SELECT bin_code FROM parcel_locations WHERE tracking_number = ?', (tracking_number,)).fetchone()
        if current_location_row is None:
            return {'error': 'parcel not found'}
        previous_bin_code_value = current_location_row[0]
        database_connection.execute('UPDATE parcel_locations SET bin_code = ? WHERE tracking_number = ?', (destination_bin_code, tracking_number))
        database_connection.commit()
        return {'from': previous_bin_code_value, 'to': destination_bin_code}
    finally:
        database_connection.close()
